1042: # The ledger entry a panel member recorded (the task's sessions.json, read tolerantly).
1043: function Find-PanelEntry {
1044:     param([string]$Path, [string]$PanelId, [int]$Position)
1045:     if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $null }
1046:     $data = $null
1047:     try { $data = ConvertFrom-Json -InputObject (Read-SharedText -Path $Path) } catch { return $null }
1048:     $found = $null
1049:     foreach ($c in @(Get-PropertyValue (Get-PropertyValue $data 'codex' $null) 'consults' @())) {
1050:         $pr = Get-PropertyValue $c 'panel' $null
1051:         if ($null -ne $pr -and [string](Get-PropertyValue $pr 'id' '') -eq $PanelId -and [string](Get-PropertyValue $pr 'position' '') -eq [string]$Position) { $found = $c }
1052:     }
1053:     return $found
1054: }
1055: 
1056: function Format-PriorCounts {
1057:     param($Entry)
1058:     $prior = @(Get-PropertyValue $Entry 'prior_findings' @() | Where-Object { $_ })
1059:     if ($prior.Count -eq 0) { return 'prior: none' }
1060:     $parts = New-Object System.Collections.Generic.List[string]
1061:     foreach ($st in $script:PriorStatuses) {
1062:         $n = @($prior | Where-Object { [string](Get-PropertyValue $_ 'status' '') -eq $st }).Count
1063:         if ($n -gt 0) { $parts.Add("$n $st") }
1064:     }
1065:     return 'prior: ' + ($parts.ToArray() -join ', ')
1066: }
