1158: # A finished (or stopped) member: its console output, its refusal line, its ledger entry and
1159: # what became of its recovery record.
1160: function Complete-PanelMember {
1161:     param($Slot)
1162:     $Slot.Lines = Read-PanelMemberOutput $Slot
1163:     $last = @($Slot.Lines | Where-Object { $_ -match '^codex-consult: ' }) | Select-Object -Last 1
1164:     $Slot.Refusal = $(if ($last) { $last -replace '^codex-consult: ', '' } else { "exit $($Slot.Exit)" })
1165:     if (-not $DryRun) {
1166:         $Slot.Entry = Find-PanelEntry -Path $sessionsPath -PanelId $panelId -Position $Slot.K
1167:         $rd = Read-PendingFile -Path $Slot.RecordPath
1168:         $Slot.RecordState = $(if ($rd.Exists -and $rd.Record) { [string](Get-PropertyValue $rd.Record 'state' '') } else { '' })
1169:     }
1170: }
1171: 
1172: # One phrase for a member that ran (the progress line; the summary builds on it).
1173: function Get-PanelMemberStatus {
1174:     param($Slot)
1175:     if ($Slot.State -eq 'killed') { return "killed by the panel after $($Slot.Wall) s (its guard: $($Slot.Guard) s)" }
1176:     if ($Slot.State -eq 'failed-start') { return "failed: could not start the member process - $($Slot.StartError)" }
1177:     if ($DryRun) { if ($Slot.Exit -eq 0) { return 'planned' } else { return "refused: $(ConvertTo-OneLine $Slot.Refusal)" } }
1178:     if ($null -ne $Slot.Entry) { return [string](Get-PropertyValue $Slot.Entry 'bridge_outcome' '') }
1179:     if ($Slot.RecordState -eq 'committing') {
1180:         # D3: the write lock never acquired (the member says so) - or stopped INSIDE its commit
1181:         # (a kill, a crash: its findings may be ORPHAN; the record names the kept reply)
1182:         if ($Slot.Refusal -match '^commit blocked:') { return "commit blocked: $(ConvertTo-OneLine ($Slot.Refusal -replace '^commit blocked:\s*', ''))" }
1183:         return "failed: stopped inside its commit (exit $($Slot.Exit)); findings it wrote have no ledger entry (ORPHAN)"
1184:     }
1185:     return "failed: $(ConvertTo-OneLine $Slot.Refusal)"
1186: }
