607: # The paths whose manifest lines (Get-RevisionInfo .manifest) differ between two
608: # fingerprints: a file that appeared, disappeared or changed (content, mode, status), in
609: # manifest order, each once. The agy engine's tree check names them (A17).
610: function Get-ManifestChanges {
611:     param([string]$Before, [string]$After)
612:     $b = @{}
613:     $a = @{}
614:     foreach ($l in @(([string]$Before) -split "`n")) { if ($l -and -not $l.StartsWith('base ')) { $b[$l] = $true } }
615:     foreach ($l in @(([string]$After) -split "`n")) { if ($l -and -not $l.StartsWith('base ')) { $a[$l] = $true } }
616:     $paths = New-Object System.Collections.Generic.List[string]
617:     foreach ($l in @($b.Keys) + @($a.Keys)) {
618:         if ($b.ContainsKey($l) -and $a.ContainsKey($l)) { continue }
619:         # "XY mode blob path[<TAB>orig]"
620:         $parts = $l.Split(' ', 4)
621:         $p = if ($parts.Count -ge 4) { $parts[3].Split("`t")[0] } else { $l }
622:         if (-not $paths.Contains($p)) { $paths.Add($p) }
623:     }
624:     $sorted = [string[]]$paths.ToArray()
625:     [Array]::Sort($sorted, [StringComparer]::Ordinal)
626:     return , $sorted
627: }
