629: # Relative path ('/'-separated) -> "<length>|<sha256>" of EVERY file under $Dir, recursively
630: # (0.4.0 wave 18: the whole collab root - every task's stores findings.json / sessions.json /
631: # state.md and handoffs - which lies outside the tree fingerprint). Left out: the bridge's
632: # own lock and recovery files (a name starting with .consult., and the atomic-write temp
633: # ..consult.*), .git directories, and directories that are reparse points (a junction or a
634: # symlink is not followed). An absent directory is an empty snapshot.
635: function Get-CollabSnapshot {
636:     param([string]$Dir)
637:     # ordinal keys: a.md and A.md are two files on a case-sensitive filesystem
638:     $snap = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
639:     if (-not $Dir -or -not [IO.Directory]::Exists($Dir)) { return $snap }
640:     $root = [IO.Path]::GetFullPath($Dir).TrimEnd([char]'\', [char]'/')
641:     $stack = New-Object System.Collections.Generic.Stack[string]
642:     $stack.Push($root)
643:     while ($stack.Count -gt 0) {
644:         $d = $stack.Pop()
645:         $info = New-Object System.IO.DirectoryInfo($d)
646:         $files = @()
647:         $subdirs = @()
648:         try { $files = @($info.GetFiles()); $subdirs = @($info.GetDirectories()) } catch { continue }
649:         foreach ($f in $files) {
650:             if ($f.Name.StartsWith('.consult.', [StringComparison]::OrdinalIgnoreCase) -or $f.Name.StartsWith('..consult.', [StringComparison]::OrdinalIgnoreCase)) { continue }
651:             $rel = $f.FullName.Substring($root.Length).TrimStart([char]'\', [char]'/').Replace('\', '/')
652:             $snap[$rel] = "$($f.Length)|$(Get-FileSha256OrMissing -Path $f.FullName)"
653:         }
654:         foreach ($s in $subdirs) {
655:             if ($s.Name -eq '.git') { continue }
656:             if (($s.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { continue }
657:             $stack.Push($s.FullName)
658:         }
659:     }
660:     return $snap
661: }
