668:     foreach ($n in @(@($Before.Keys) + @($After.Keys) | Select-Object -Unique)) {
669:         $skip = $false
670:         foreach ($pfx in @($IgnorePrefixes)) { if ($pfx -and $n.StartsWith($pfx, [StringComparison]::OrdinalIgnoreCase)) { $skip = $true } }
