266: # Argument quoting: bare token when it is safe, otherwise wrap in double quotes and
267: # double any embedded quote. This is the Windows CRT rule, which is also what
268: # .NET's Process argument parser implements on macOS/Linux, so one form serves both.
269: # It is what survives the npm codex.cmd shim on Windows.
270: function ConvertTo-ProcArg {
271:     param([string]$Value)
272:     if ($Value -eq '-') { return $Value }
273:     if ($Value -match '^[A-Za-z0-9_.\-:\\/=]+$') { return $Value }
274:     return '"' + ($Value -replace '"', '""') + '"'
275: }
