286: # Runs git with the output captured as raw BYTES (NUL-separated `-z` output must not
287: # go through PowerShell's line splitting or a console code page). stdin is not
288: # redirected: on .NET Framework the child's stdin writer can emit a UTF-8 preamble
289: # (chcp 65001), so paths travel as arguments instead. Returns $null when git cannot
290: # be started, else { ExitCode; Bytes }.
291: function Invoke-GitCapture {
292:     param([string]$Root, [string[]]$GitArgs)
293:     try {
294:         $psi = New-Object System.Diagnostics.ProcessStartInfo
295:         $psi.FileName = 'git'
296:         $psi.WorkingDirectory = $Root
297:         $psi.UseShellExecute = $false
298:         $psi.CreateNoWindow = $true
299:         $psi.RedirectStandardOutput = $true
300:         $psi.RedirectStandardError = $true
301:         if ($null -ne $psi.PSObject.Properties['ArgumentList']) {
302:             # .NET Core / PowerShell 7: no quoting rules to get wrong (paths may hold
303:             # quotes or newlines outside Windows).
304:             foreach ($a in $GitArgs) { $psi.ArgumentList.Add($a) }
305:         } else {
306:             # .NET Framework = Windows, where paths cannot contain '"' or newlines.
307:             $psi.Arguments = (($GitArgs | ForEach-Object { ConvertTo-ProcArg $_ }) -join ' ')
308:         }
309:         $p = [System.Diagnostics.Process]::Start($psi)
310:         try {
311:             $ms = New-Object System.IO.MemoryStream
312:             $copy = $p.StandardOutput.BaseStream.CopyToAsync($ms)
313:             $err = $p.StandardError.ReadToEndAsync()
314:             $p.WaitForExit()
315:             $copy.Wait()
316:             $null = $err.Wait(5000)
317:             return [pscustomobject]@{ ExitCode = $p.ExitCode; Bytes = $ms.ToArray() }
318:         } finally {
319:             $p.Dispose()
320:         }
321:     } catch {
322:         return $null
323:     }
324: }
