490: function Get-RevisionInfo {
491:     param([string]$Root, [string]$CollabRoot = '')
492:     $info = [pscustomobject]@{
493:         base_commit       = 'unknown'
494:         short_sha         = 'unknown'
495:         dirty             = $false
496:         reviewed_revision = 'unknown'
497:         tree_sha256       = ''
498:         changed_files     = 0
499:         fingerprint_note  = 'no git'
500:         manifest          = ''
501:     }
502:     $status = Invoke-GitCapture -Root $Root -GitArgs @('--no-optional-locks', 'status', '--porcelain=v1', '-uall', '-z')
503:     if (-not $status -or $status.ExitCode -ne 0) { return $info }
504: 
505:     $notes = New-Object System.Collections.Generic.List[string]
506:     $head = Get-GitOutput -Root $Root -GitArgs @('rev-parse', '--verify', '-q', 'HEAD')
507:     $base = 'none'
508:     if ($head) {
509:         $base = ([string]@($head)[0]).Trim()
510:         $info.base_commit = $base
511:         $short = Get-GitOutput -Root $Root -GitArgs @('rev-parse', '--short', 'HEAD')
512:         if ($short) { $info.short_sha = ([string]@($short)[0]).Trim() }
513:     } else {
514:         $notes.Add('no commits yet')
515:     }
516: 
517:     $collabRel = $null
518:     if ($CollabRoot) {
519:         $collabRel = Get-RepoRelativePath -Root $Root -Path $CollabRoot
520:         if ($null -eq $collabRel) { $notes.Add('collab dir outside the repository') }
521:         elseif ($collabRel -eq '') { $notes.Add('collab dir is the repository root: nothing excluded'); $collabRel = $null }
522:     }
523:     $cmp = if ($script:OnWindows) { [StringComparison]::OrdinalIgnoreCase } else { [StringComparison]::Ordinal }
524: 
525:     # Parse the NUL-separated entries: "XY <path>", and for a rename or copy the
526:     # source path follows as the next NUL-terminated field.
527:     $tokens = $script:Utf8NoBom.GetString($status.Bytes).Split([char]0)
528:     $entries = New-Object System.Collections.Generic.List[object]
529:     $excluded = 0
530:     $i = 0
531:     while ($i -lt $tokens.Length) {
532:         $tok = $tokens[$i]
533:         $i++
534:         if ($tok.Length -lt 4) { continue }
535:         $xy = $tok.Substring(0, 2)
536:         $path = $tok.Substring(3)
537:         $orig = $null
538:         if ($xy[0] -ceq 'R' -or $xy[0] -ceq 'C' -or $xy[1] -ceq 'R' -or $xy[1] -ceq 'C') {
539:             if ($i -lt $tokens.Length) { $orig = $tokens[$i]; $i++ }
540:         }
541:         if ($collabRel -and ($path.Equals($collabRel, $cmp) -or $path.StartsWith($collabRel + '/', $cmp))) {
542:             $excluded++
543:             continue
544:         }
545:         $entries.Add([pscustomobject]@{ XY = $xy; Path = $path; Orig = $orig; Blob = ''; Mode = 'u' })
546:     }
547: 
548:     $modeMap = New-PathMap
549:     if ($head) { $modeMap = Get-GitModeMap -Root $Root }
550:     else { $notes.Add('tracked file modes not recorded (no HEAD to compare with)') }
551:     foreach ($e in $entries) {
552:         if ($e.XY -eq '??' -or -not $head) { continue }
553:         if ($modeMap.ContainsKey($e.Path)) { $e.Mode = $modeMap[$e.Path] } else { $e.Mode = '=' }
554:     }
555: 
556:     $toHash = New-Object System.Collections.Generic.List[string]
557:     $dirs = 0
558:     foreach ($e in $entries) {
559:         $full = [IO.Path]::Combine($Root, $e.Path)
560:         if ([IO.Directory]::Exists($full)) { $e.Blob = 'dir'; $dirs++ }
561:         elseif ([IO.File]::Exists($full)) { $toHash.Add($e.Path) }
562:         else { $e.Blob = 'deleted' }
563:     }
564:     if ($toHash.Count -gt 0) {
565:         $ids = Get-GitBlobIds -Root $Root -Paths $toHash.ToArray()
566:         foreach ($e in $entries) {
567:             if ($e.Blob) { continue }
568:             $id = $null
569:             if ($ids.TryGetValue($e.Path, [ref]$id)) { $e.Blob = $id } else { $e.Blob = 'unreadable' }
570:         }
571:     }
572:     $unreadable = @($entries | Where-Object { $_.Blob -eq 'unreadable' }).Count
573: 
574:     $keys = New-Object System.Collections.Generic.List[string]
575:     $lines = New-Object System.Collections.Generic.List[string]
576:     foreach ($e in $entries) {
577:         $line = $e.XY + ' ' + $e.Mode + ' ' + $e.Blob + ' ' + (ConvertTo-ManifestPath $e.Path)
578:         if ($null -ne $e.Orig) { $line += "`t" + (ConvertTo-ManifestPath $e.Orig) }
579:         $keys.Add($e.Path + [char]0 + $line)
580:         $lines.Add($line)
581:     }
582:     $keyArr = $keys.ToArray()
583:     $lineArr = $lines.ToArray()
584:     [Array]::Sort($keyArr, $lineArr, [StringComparer]::Ordinal)
585:     $sb = New-Object System.Text.StringBuilder
586:     [void]$sb.Append("base $base`n")
587:     foreach ($l in $lineArr) { [void]$sb.Append($l + "`n") }
588:     $manifest = $sb.ToString()
589: 
590:     if ($collabRel) { $notes.Add("collab dir '$collabRel' excluded ($excluded entries)") }
591:     $notes.Add('ignored files excluded')
592:     $notes.Add('untracked file modes not recorded')
593:     if ($dirs -gt 0) { $notes.Add("submodules not recursed ($dirs directory entries)") }
594:     else { $notes.Add('submodules not recursed') }
595:     if ($unreadable -gt 0) { $notes.Add("$unreadable files unreadable") }
596: 
597:     $info.manifest = $manifest
598:     $info.tree_sha256 = Get-Sha256Hex -Bytes ($script:Utf8NoBom.GetBytes($manifest))
599:     $info.changed_files = $entries.Count
600:     $info.dirty = ($entries.Count -gt 0)
